    [TestClass]
    public class TripledLaminatedGlassTest1
    {
        [TestMethod]
        public void TestSpatial1()
        {
            Node[] nodesPlate1 = new Node[4];
            nodesPlate1[0] = new Node(-1.0, -1.0, 0, "1");
            nodesPlate1[1] = new Node(1.0, -1.0, 0, "2");
            nodesPlate1[2] = new Node(1.0, 1.0, 0, "3");
            nodesPlate1[3] = new Node(-1.0, 1.0, 0, "4");

            //general values §6 of article
            double G0 = 0.5173;
            double h0 = 0.38;
            double h1 = 2.875;
            double h2 = 2.875;
            double EGlass = 72000.0;
            double niGlass = 0.23;
            FiniteElement e0 = new Quad4TripleLaminatedGlass(nodesPlate1, G0, h0, h1, h2, EGlass, niGlass);
            e0.BuildMatrix();

            Node[] nodesPlate2 = new Node[4];
            nodesPlate2[0] = new Node(0.0, 0.0, 0, "1");
            nodesPlate2[1] = new Node(2.0, 0.0, 0, "2");
            nodesPlate2[2] = new Node(2.0, 2.0, 0, "3");
            nodesPlate2[3] = new Node(0.0, 2.0, 0, "4");

            FiniteElement e1 = new Quad4TripleLaminatedGlass(nodesPlate2, G0, h0, h1, h2, EGlass, niGlass);
            e1.BuildMatrix();

            for (int i = 0; i < e1.KElementGlobalCoord.RowCount; i++)
            {
                for (int j = 0; j < e1.KElementGlobalCoord.RowCount; j++)
                {
                    Assert.AreEqual(e0.KElementGlobalCoord[i,j], e1.KElementGlobalCoord[i, j]);
                }
            }
        }

        [TestMethod]
        public void EquivalentNodalForce()
        {
            Node[] nodesPlate1 = new Node[4];
            nodesPlate1[0] = new Node(0.0, 0.0, 0, "1");
            nodesPlate1[1] = new Node(2.0, 0.0, 0, "2");
            nodesPlate1[2] = new Node(2.0, 2.0, 0, "3");
            nodesPlate1[3] = new Node(0.0, 2.0, 0, "4");

            //general values §6 of article
            double G0 = 0.5173;
            double h0 = 0.38;
            double h1 = 2.875;
            double h2 = 2.875;
            double EGlass = 72000.0;
            double niGlass = 0.23;
            Quad4TripleLaminatedGlass e0 = new Quad4TripleLaminatedGlass(nodesPlate1, G0, h0, h1, h2, EGlass, niGlass);

            CoordinateSystem csys = new CoordinateSystem(new Vector3d(0, 0, 0), new Vector3d(1, 0, 0), new Vector3d(0, 1, 0));
            PlatePressureAttribute p = new PlatePressureAttribute("lc", csys, 0, 0, 1);

            e0.AddLoadCaseAttribute(p);

            CoordinateSystem sys = new CoordinateSystem(new Point3d(0, 0, 0), new Point3d(1, 0, 0), new Point3d(0, 1, 0));
            NodeRestrainAttribute fix = new NodeRestrainAttribute("freedomCase", sys);
            fix.AddExternalRestrain(Solver.DOF.DX);
            fix.AddExternalRestrain(Solver.DOF.DY);
            fix.AddExternalRestrain(Solver.DOF.DZ);
            fix.AddExternalRestrain(Solver.DOF.RX);
            fix.AddExternalRestrain(Solver.DOF.RY);
            fix.AddExternalRestrain(Solver.DOF.RZ);

            nodesPlate1[0].AddAttribute(fix);
            nodesPlate1[1].AddAttribute(fix);
            nodesPlate1[2].AddAttribute(fix);
            nodesPlate1[3].AddAttribute(fix);

            LinearSolver solver = new LinearSolver(new FiniteElement[] { e0 });

            Assert.AreEqual(0.0, solver.F[0], 1e-4);
            Assert.AreEqual(0.0, solver.F[1], 1e-4);
            Assert.AreEqual(1.0, solver.F[2], 1e-4);
            Assert.AreEqual(1.0 / 3.0, solver.F[3], 1e-4);
            Assert.AreEqual(-1.0 / 3.0, solver.F[4], 1e-4);
            Assert.AreEqual(1.0 / 9.0, solver.F[5], 1e-4);

            Assert.AreEqual(0.0, solver.F[6], 1e-4);
            Assert.AreEqual(0.0, solver.F[7], 1e-4);
            Assert.AreEqual(1.0, solver.F[8], 1e-4);
            Assert.AreEqual(1.0 / 3.0, solver.F[9], 1e-4);
            Assert.AreEqual(1.0 / 3.0, solver.F[10], 1e-4);
            Assert.AreEqual(-1.0 / 9.0, solver.F[11], 1e-4);

            Assert.AreEqual(0.0, solver.F[12], 1e-4);
            Assert.AreEqual(0.0, solver.F[13], 1e-4);
            Assert.AreEqual(1.0, solver.F[14], 1e-4);
            Assert.AreEqual(-1.0 / 3.0, solver.F[15], 1e-4);
            Assert.AreEqual(1.0 / 3.0, solver.F[16], 1e-4);
            Assert.AreEqual(1.0 / 9.0, solver.F[17], 1e-4);

            Assert.AreEqual(0.0, solver.F[18], 1e-4);
            Assert.AreEqual(0.0, solver.F[19], 1e-4);
            Assert.AreEqual(1.0, solver.F[20], 1e-4);
            Assert.AreEqual(-1.0 / 3.0, solver.F[21], 1e-4);
            Assert.AreEqual(-1.0 / 3.0, solver.F[22], 1e-4);
            Assert.AreEqual(-1.0 / 9.0, solver.F[23], 1e-4);
        }

        [TestMethod]
        public void TestDg()
        {
            List<Node> nodes = new List<Node>();
            nodes.Add(new Node(0.0, 0.0, 0));
            nodes.Add(new Node(1.0, 0.0, 0));
            nodes.Add(new Node(1.0, 1.0, 0));
            nodes.Add(new Node(0.0, 1.0, 0));

            double h1 = 0.5;
            double h2 = 0.5;
            double EGlass = 12.0;
            double niGlass = 0.0;
            double G0 = EGlass / (2.0 * (1.0 + niGlass));
            double h0 = 0.00001;

            Quad4TripleLaminatedGlass e0 = new Quad4TripleLaminatedGlass(new Node[] { nodes[0], nodes[1], nodes[2], nodes[3] }, G0, h0, h1, h2, EGlass, niGlass);
            e0.BuildMatrix();

            mnl.Matrix<double> dgManual = mnl.Matrix<double>.Build.Dense(6, 6);
            dgManual[0, 0] = 3.0;
            dgManual[1, 1] = 3.0;
            dgManual[2, 2] = 1.5;

            dgManual[3, 3] = 0.25;
            dgManual[4, 4] = 0.25;
            dgManual[5, 5] = 0.125;

            for (int r = 0; r < e0.Dg.RowCount; r++)
            {
                for (int c = 0; c < e0.Dg.ColumnCount; c++)
                {
                    Assert.AreEqual(dgManual[r,c], e0.Dg[r,c], 0.001);
                }
            }
        }

        [TestMethod]
        public void TestDs()
        {
            List<Node> nodes = new List<Node>();
            nodes.Add(new Node(0.0, 0.0, 0));
            nodes.Add(new Node(1.0, 0.0, 0));
            nodes.Add(new Node(1.0, 1.0, 0));
            nodes.Add(new Node(0.0, 1.0, 0));

            double h1 = 0.5;
            double h2 = 0.5;
            double EGlass = 12.0;
            double niGlass = 0.0;
            double G0 = EGlass / (2.0 * (1.0 + niGlass));
            double h0 = 0.1;

            Quad4TripleLaminatedGlass e0 = new Quad4TripleLaminatedGlass(new Node[] { nodes[0], nodes[1], nodes[2], nodes[3] }, G0, h0, h1, h2, EGlass, niGlass);
            e0.BuildMatrix();

            mnl.Matrix<double> dsManual = mnl.Matrix<double>.Build.Dense(4, 4);
            dsManual[0, 0] = 60;
            dsManual[0, 2] = 36;

            dsManual[1, 1] = 60;
            dsManual[1, 3] = 36;

            dsManual[2, 0] = 36;
            dsManual[2, 2] = 21.6;

            dsManual[3, 1] = 36;
            dsManual[3, 3] = 21.6;
            
            for (int r = 0; r < e0.Ds.RowCount; r++)
            {
                for (int c = 0; c < e0.Ds.ColumnCount; c++)
                {
                    Assert.AreEqual(dsManual[r, c], e0.Ds[r, c], 0.001);
                }
            }
        }

        [TestMethod]
        public void TestN()
        {
            List<Node> nodes = new List<Node>();
            nodes.Add(new Node(0.0, 0.0, 0));
            nodes.Add(new Node(2.0, 0.0, 0));
            nodes.Add(new Node(2.0, 2.0, 0));
            nodes.Add(new Node(0.0, 2.0, 0));

            double h1 = 0.5;
            double h2 = 0.5;
            double EGlass = 12.0;
            double niGlass = 0.0;
            double G0 = EGlass / (2.0 * (1.0 + niGlass));
            double h0 = 0.1;

            Quad4TripleLaminatedGlass e0 = new Quad4TripleLaminatedGlass(new Node[] { nodes[0], nodes[1], nodes[2], nodes[3] }, G0, h0, h1, h2, EGlass, niGlass);

            e0.BuildMatrix();

            var m = e0.GetNMatrix(0, 0);
            FEMUtilities.WriteMatrix(m);

            Assert.AreEqual(1.0, m[0,0], 0.001);
            Assert.AreEqual(1.0,  m[1,1], 0.001);
            Assert.AreEqual(1.0, m[2,2], 0.001);

            m = e0.GetNMatrix(2, 0);
            FEMUtilities.WriteMatrix(m);
            Assert.AreEqual(1.0, m[0, 6], 0.001);
            Assert.AreEqual(1.0, m[1, 7], 0.001);
            Assert.AreEqual(1.0, m[2, 8], 0.001);

            m = e0.GetNMatrix(2, 2);
            FEMUtilities.WriteMatrix(m);
            Assert.AreEqual(1.0, m[0, 12], 0.001);
            Assert.AreEqual(1.0, m[1, 13], 0.001);
            Assert.AreEqual(1.0, m[2, 14], 0.001);

            m = e0.GetNMatrix(0, 2);
            FEMUtilities.WriteMatrix(m);
            Assert.AreEqual(1.0, m[0, 18], 0.001);
            Assert.AreEqual(1.0, m[1, 19], 0.001);
            Assert.AreEqual(1.0, m[2, 20], 0.001);
        }

