            els.Add(new Quad4TripleLaminatedGlass(new Node[] { nodes[1347], nodes[1542], nodes[1549], nodes[2] }, G0, hInterlayer, hGlass, hGlass, EGlass, niGlass));
            els.Add(new Quad4TripleLaminatedGlass(new Node[] { nodes[1542], nodes[1543], nodes[1550], nodes[1549] }, G0, hInterlayer, hGlass, hGlass, EGlass, niGlass));
            els.Add(new Quad4TripleLaminatedGlass(new Node[] { nodes[1543], nodes[1544], nodes[1551], nodes[1550] }, G0, hInterlayer, hGlass, hGlass, EGlass, niGlass));
            els.Add(new Quad4TripleLaminatedGlass(new Node[] { nodes[1544], nodes[1545], nodes[1552], nodes[1551] }, G0, hInterlayer, hGlass, hGlass, EGlass, niGlass));
            els.Add(new Quad4TripleLaminatedGlass(new Node[] { nodes[1545], nodes[1546], nodes[1553], nodes[1552] }, G0, hInterlayer, hGlass, hGlass, EGlass, niGlass));
            els.Add(new Quad4TripleLaminatedGlass(new Node[] { nodes[1546], nodes[1547], nodes[1554], nodes[1553] }, G0, hInterlayer, hGlass, hGlass, EGlass, niGlass));
            #endregion

            CoordinateSystem sys = new CoordinateSystem(new Point3d(0, 0, 0), new Point3d(1, 0, 0), new Point3d(0, 1, 0));

            #region force
            PlatePressureAttribute pressure = new PlatePressureAttribute("loadCase", sys, 0.0, 0.0, (2.418 / 1000.0 * 9.81) * (hTot / 1000.0));
            els.ForEach(x => x.AddLoadCaseAttribute(pressure));

            NodeForceAttribute fNode = new NodeForceAttribute("loadCase", sys, 0, 0, (F / 2.0) / 21.0, 0, 0, 0);
            nodes.Where(x => x.Position.X == 15).ToList().ForEach(x => x.AddAttribute(fNode));
            #endregion

            #region restrains
            NodeRestrainAttribute x0Restrain = new NodeRestrainAttribute("freedomCase", sys);
            x0Restrain.AddExternalRestrain(Solver.DOF.DX);
            x0Restrain.AddExternalRestrain(Solver.DOF.RY);
            nodes.Where(x => x.Position.X == 0).ToList().ForEach(x => x.AddAttribute(x0Restrain));

            NodeRestrainAttribute x330Restrain = new NodeRestrainAttribute("freedomCase", sys);
            x330Restrain.AddExternalRestrain(Solver.DOF.DZ);
            nodes.Where(x => x.Position.X == 330).ToList().ForEach(x => x.AddAttribute(x330Restrain));
            #endregion

            LinearSolver fem = new LinearSolver(els.ToArray());

            double DZTLG = fem.GetNodeDisplacementGlobalCoordinates(nodes.Where(x => x.Position.X == 0 && x.Position.Y == 0).First(), Solver.DOF.DZ);
            Console.WriteLine("displacement triple laminated glass = " + DZTLG);

            Assert.AreEqual(3.731, DZTLG, 0.01);
        }

