            #endregion

            CoordinateSystem sys = new CoordinateSystem(new Point3d(0, 0, 0), new Point3d(1, 0, 0), new Point3d(0, 1, 0));

            #region restrains
            NodeRestrainAttribute x0Restrain = new NodeRestrainAttribute("freedomCase", sys);
            x0Restrain.AddExternalRestrain(Solver.DOF.DX);
            nodes.Where(x => x.Position.X == 0).ToList().ForEach(x => x.AddAttribute(x0Restrain));

            NodeRestrainAttribute y0Restrain = new NodeRestrainAttribute("freedomCase", sys);
            y0Restrain.AddExternalRestrain(Solver.DOF.DY);
            nodes.Where(x => x.Position.Y == 0).ToList().ForEach(x => x.AddAttribute(y0Restrain));

            NodeRestrainAttribute simplySupport = new NodeRestrainAttribute("freedomCase", sys);
            simplySupport.AddExternalRestrain(Solver.DOF.DZ);
            nodes.Where(x => x.Position.X <= (525 - 45) && x.Position.Y == (375 - 45)).ToList().ForEach(x => x.AddAttribute(simplySupport));
            nodes.Where(x => x.Position.X == (525 - 45) && x.Position.Y <= (375 - 45)).ToList().ForEach(x => x.AddAttribute(simplySupport));
            #endregion

            #region forces
            PlatePressureAttribute pressure = new PlatePressureAttribute("loadCase", sys, 0.0, 0.0, (2.418 / 1000.0 * 9.81) * (hTot / 1000.0));
            els.ForEach(x => x.AddLoadCaseAttribute(pressure));

            PlatePressureAttribute pressureMass = new PlatePressureAttribute("loadCase", sys, 0.0, 0.0, F / (3*3*(5*5)));
            bool seachPlates(Plate p)
            {
                for (int i = 0; i < p.Nodes.Count(); i++)
                {
                    if (p.Nodes[i].Position.X > 15.0 || p.Nodes[i].Position.Y > 15.0)
                    {
                        return false;
                    }
                }
                return true;
            }
            els.Where(seachPlates).ToList().ForEach(x => x.AddLoadCaseAttribute(pressure));
            #endregion

            LinearSolver fem = new LinearSolver(els.ToArray());

            double DZTLG = fem.GetNodeDisplacementGlobalCoordinates(nodes.Where(x => x.Position.X == 0 && x.Position.Y == 0).First(), Solver.DOF.DZ);
            Console.WriteLine("displacement triple laminated glass = " + DZTLG);

            //Assert.AreEqual(2.76, DZTLG, 0.01);
        }

