            CoordinateSystem sys = new CoordinateSystem(new Point3d(0, 0, 0), new Point3d(1, 0, 0), new Point3d(0, 1, 0));

            int nrNodesY = nodes.Where(x => x.Position.X == 0).Count();
            NodeForceAttribute fNode = new NodeForceAttribute("loadCase", sys, 0, 0, (F / nrNodesY), 0, 0, 0);
            nodes.Where(x => x.Position.X == 0).ToList().ForEach(x => x.AddAttribute(fNode));

            NodeRestrainAttribute x1100Restrain = new NodeRestrainAttribute("freedomCase", sys);
            //x1100Restrain.AddExternalRestrain(Solver.DOF.DX);
            //x1100Restrain.AddExternalRestrain(Solver.DOF.DY);
            x1100Restrain.AddExternalRestrain(Solver.DOF.DZ);
            //x1100Restrain.AddExternalRestrain(Solver.DOF.RX);
            x1100Restrain.AddExternalRestrain(Solver.DOF.RY);
            //x1100Restrain.AddExternalRestrain(Solver.DOF.RZ);
            nodes.Where(x => x.Position.X == 1100).ToList().ForEach(x => x.AddAttribute(x1100Restrain));

            LinearSolver fem = new LinearSolver(els.ToArray());

            double DZTLG = fem.GetNodeDisplacementGlobalCoordinates(nodes.Where(x => x.Position.X == 0 && x.Position.Y == 0).First(), Solver.DOF.DZ);
            Console.WriteLine("displacement triple laminated glass = " + DZTLG);
            Assert.AreEqual(56.01, DZTLG, 0.01);
        }

        [TestMethod]
        ///Reference to Conjugate-beam analogy for inflexed laminates
        public void SimplySupportedRoyerTest1()
        {
            /*
            Geometria:
            L = 2000 mm
            b = 500 mm
            
            H1 = 10 mm
            H2 = 6 mm
            HInterlayer = 0.76 mm

            Forza
            q = 0.5 kN/m

            Materiali
            E = 70000 MPa
            Ni = 0.22
            Ginterlayer = 0.1 MPa
            */

            double p = 0.5; //kN/m
            double b = 500.0; //mm
            double q = (p * 1000.0) / (1000.0) / b; //N/mm2
            Console.WriteLine("q=" + q + " N/mm2");

            double EGlass = 70000.0;
            double niGlass = 0.22;

            double G0 = 0.10;

            double hGlass1 = 6.0;
            double hGlass2 = 10.0;
            double hInterlayer = 0.76;

            List<Node> nodes = new List<Node>();
            #region nodes
            nodes.Add(new Node(-1e6, -1e6, -1e6));
            nodes.Add(new Node(0, 0, 0));
            nodes.Add(new Node(2000, 0, 0));
            nodes.Add(new Node(2000, 500, 0));
            nodes.Add(new Node(0, 500, 0));
            nodes.Add(new Node(100, 0, 0));
            nodes.Add(new Node(200, 0, 0));
            nodes.Add(new Node(300, 0, 0));
            nodes.Add(new Node(400, 0, 0));
            nodes.Add(new Node(500, 0, 0));
            nodes.Add(new Node(600, 0, 0));
            nodes.Add(new Node(700, 0, 0));
